package com.smartgrading.backend.controller;
import com.smartgrading.backend.dto.*; import com.smartgrading.backend.service.SubmissionService; import jakarta.validation.Valid; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class SubmissionController { private final SubmissionService service; public SubmissionController(SubmissionService s){service=s;} @PostMapping("/assignments/{assignmentId}/submissions") @ResponseStatus(HttpStatus.CREATED) public SubmissionResponse create(@PathVariable Integer assignmentId,@RequestBody SubmissionRequest r){return service.create(assignmentId,r);} @GetMapping("/submissions/{id}") public SubmissionResponse get(@PathVariable Integer id){return service.get(id);} @GetMapping("/assignments/{id}/submissions") public List<SubmissionResponse> assignment(@PathVariable Integer id){return service.byAssignment(id);} @GetMapping("/submissions/student/{id}") public List<SubmissionResponse> student(@PathVariable Integer id){return service.byStudent(id);} @PostMapping("/submissions/{id}/answers") @ResponseStatus(HttpStatus.CREATED) public StudentAnswerResponse answer(@PathVariable Integer id,@Valid @RequestBody StudentAnswerRequest r){return service.answer(id,r);} @GetMapping("/submissions/{id}/answers") public List<StudentAnswerResponse> answers(@PathVariable Integer id){return service.answers(id);} @PutMapping("/answers/{id}") public StudentAnswerResponse updateAnswer(@PathVariable Integer id,@Valid @RequestBody AnswerUpdateRequest r){return service.updateAnswer(id,r);} @PostMapping("/submissions/{id}/review") public SubmissionResponse markReviewed(@PathVariable Integer id){return service.transition(id,com.smartgrading.backend.entity.SubmissionStatus.REVIEWED);} }
